#include <cstdint>
#include <functional>
#include <map>
#include <optional>
#include <string>
#include <vector>

using DWORD = std::uint32_t;
constexpr DWORD ERROR_ENVVAR_NOT_FOUND = 203;
inline std::map<std::wstring, std::wstring> g_variables;
inline DWORD g_lastError{ 0 };
inline std::function<void()> g_beforeCall;

DWORD FakeGetVariable(const wchar_t* name, wchar_t* buffer, DWORD size)
{
    if (g_beforeCall) g_beforeCall();
    const auto it{ g_variables.find(name) };
    if (it == g_variables.end()) { g_lastError = ERROR_ENVVAR_NOT_FOUND; return 0; }
    const auto length{ static_cast<DWORD>(it->second.size()) };
    if (buffer == nullptr || size < length + 1) return length + 1;
    it->second.copy(buffer, length);
    buffer[length] = L'\0';
    g_lastError = 0;
    return length;
}

std::optional<std::wstring> readVariable(const std::wstring& name)
{
    DWORD needed{ FakeGetVariable(name.c_str(), nullptr, 0) };
    for (;;)
    {
        if (needed == 0) return std::nullopt;
        std::vector<wchar_t> buffer(needed);
        const DWORD result{ FakeGetVariable(name.c_str(), buffer.data(), needed) };
        if (result == 0)
        {
            if (g_lastError == ERROR_ENVVAR_NOT_FOUND) return std::nullopt;
            return std::wstring{};
        }
        if (result < needed) return std::wstring(buffer.data(), result);
        needed = result;
    }
}

unitTests:
void reset() { g_variables.clear(); g_beforeCall = nullptr; g_lastError = 0; }
TEST("reading a value") {
    reset();
    g_variables[L"PATH"] = L"C:\\Windows;C:\\Tools";
    CHECK(readVariable(L"PATH") == std::optional<std::wstring>{ L"C:\\Windows;C:\\Tools" });
    g_variables[L"ONE"] = L"x";
    CHECK(readVariable(L"ONE") == std::optional<std::wstring>{ L"x" });
}
TEST("missing and empty are different") {
    reset();
    CHECK(!readVariable(L"NOPE").has_value());
    g_variables[L"EMPTY"] = L"";
    const auto empty{ readVariable(L"EMPTY") };
    CHECK(empty.has_value() && empty->empty());
}
TEST("a value that grows between the calls") {
    reset();
    g_variables[L"GROWS"] = L"short";
    int calls{ 0 };
    g_beforeCall = [&] {
        if (++calls == 2) g_variables[L"GROWS"] = L"a much longer value than before";
    };
    CHECK(readVariable(L"GROWS") == std::optional<std::wstring>{ L"a much longer value than before" });
    CHECK_EQ(calls, 3);
}
TEST("a value that shrinks or disappears between the calls") {
    reset();
    g_variables[L"SHRINKS"] = L"quite a long value";
    int calls{ 0 };
    g_beforeCall = [&] { if (++calls == 2) g_variables[L"SHRINKS"] = L"tiny"; };
    CHECK(readVariable(L"SHRINKS") == std::optional<std::wstring>{ L"tiny" });
    reset();
    g_variables[L"GOES"] = L"here now";
    calls = 0;
    g_beforeCall = [&] { if (++calls == 2) g_variables.erase(L"GOES"); };
    CHECK(!readVariable(L"GOES").has_value());
    reset();
    g_variables[L"EMPTIES"] = L"value";
    calls = 0;
    g_beforeCall = [&] { if (++calls == 2) g_variables[L"EMPTIES"] = L""; };
    const auto e{ readVariable(L"EMPTIES") };
    CHECK(e.has_value() && e->empty());
    reset();
}

